using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        var errors = new List<(string project, string code, string message, string file, int line)>();
        var warnings = new List<(string project, string code, string message, string file, int line)>();

        build.VisitAllChildren<Error>(e => {
            var proj = GetParentProject(e);
            errors.Add((proj, e.Code ?? "", e.Text ?? e.ToString(), e.File ?? "", e.LineNumber));
        });

        build.VisitAllChildren<Warning>(w => {
            var proj = GetParentProject(w);
            warnings.Add((proj, w.Code ?? "", w.Text ?? w.ToString(), w.File ?? "", w.LineNumber));
        });

        // Print project structure
        Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===");
        Console.WriteLine();

        // Show all projects and their results
        Console.WriteLine("=== PROJECTS ===");
        build.VisitAllChildren<Project>(p => {
            Console.WriteLine($"  [{(p.Succeeded ? "OK" : "FAIL")}] {p.Name}");
        });
        Console.WriteLine();

        Console.WriteLine($"=== ERRORS ({errors.Count}) ===");
        foreach (var e in errors)
        {
            Console.WriteLine($"  Project: {e.project}");
            Console.WriteLine($"  Code:    {e.code}");
            Console.WriteLine($"  File:    {e.file}:{e.line}");
            Console.WriteLine($"  Message: {e.message}");
            Console.WriteLine();
        }

        if (warnings.Count > 0)
        {
            Console.WriteLine($"=== WARNINGS ({warnings.Count}) ===");
            foreach (var w in warnings)
            {
                Console.WriteLine($"  Project: {w.project}");
                Console.WriteLine($"  Code:    {w.code}");  
                Console.WriteLine($"  File:    {w.file}:{w.line}");
                Console.WriteLine($"  Message: {w.message}");
                Console.WriteLine();
            }
        }
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "unknown";
            current = current.Parent;
        }
        return "unknown";
    }
}
