using System;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Dump messages about project references and dependency failures
        Console.WriteLine("=== PROJECT REFERENCE ITEMS ===");
        build.VisitAllChildren<AddItem>(item => {
            if (item.Name == "ProjectReference")
            {
                var proj = GetParentProject(item);
                foreach (var child in item.Children)
                {
                    Console.WriteLine($"  {proj} -> {child}");
                }
            }
        });
        Console.WriteLine();

        // Look for MSB error messages (dependency build failures)
        Console.WriteLine("=== MSB/DEPENDENCY MESSAGES ===");
        build.VisitAllChildren<Message>(m => {
            if (m.Text != null && (m.Text.Contains("MSB") || m.Text.Contains("failed") || m.Text.Contains("depends on")))
            {
                var proj = GetParentProject(m);
                Console.WriteLine($"  [{proj}] {m.Text.Substring(0, Math.Min(m.Text.Length, 200))}");
            }
        });
        Console.WriteLine();

        // Check for build failures at target level
        Console.WriteLine("=== FAILED TARGETS ===");
        build.VisitAllChildren<Target>(t => {
            var succeeded = t.GetType().GetProperty("Succeeded");
            if (succeeded != null)
            {
                var val = succeeded.GetValue(t);
                if (val is bool b && !b)
                {
                    var proj = GetParentProject(t);
                    Console.WriteLine($"  [{proj}] Target: {t.Name}");
                }
            }
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "unknown";
            current = current.Parent;
        }
        return "unknown";
    }
}
