using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Look at all Item types
        var seen = new System.Collections.Generic.HashSet<string>();
        build.VisitAllChildren<AddItem>(item => {
            if (seen.Add(item.Name))
                Console.Write(item.Name + ", ");
        });
        Console.WriteLine();
        Console.WriteLine();

        // NUGET-RELATED ITEMS
        Console.WriteLine("=== NUGET-RELATED ITEMS ===");
        build.VisitAllChildren<AddItem>(item => {
            if (item.Name.Contains("Package") || item.Name.Contains("Nuget") || item.Name.Contains("nuget") || item.Name.Contains("NuGet"))
            {
                var proj = GetParentProject(item);
                foreach (var child in item.Children)
                    Console.WriteLine($"  [{proj}] {item.Name}: {child}");
            }
        });

        // Also look for Newtonsoft in any messages
        Console.WriteLine();
        Console.WriteLine("=== NEWTONSOFT MENTIONS ===");
        build.VisitAllChildren<Message>(m => {
            if (m.Text?.Contains("Newtonsoft") == true)
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 300))}");
        });

        // Check source files referenced  
        Console.WriteLine();
        Console.WriteLine("=== COMPILE ITEMS ===");
        build.VisitAllChildren<AddItem>(item => {
            if (item.Name == "Compile")
            {
                var proj = GetParentProject(item);
                foreach (var child in item.Children)
                    Console.WriteLine($"  [{proj}] {child}");
            }
        });

        // Check project dependency chain
        Console.WriteLine();
        Console.WriteLine("=== PROJECT REFERENCES ===");
        build.VisitAllChildren<AddItem>(item => {
            if (item.Name == "ProjectReference")
            {
                var proj = GetParentProject(item);
                foreach (var child in item.Children)
                    Console.WriteLine($"  [{proj}] -> {child}");
            }
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "unknown";
            current = current.Parent;
        }
        return "unknown";
    }
}
